import{_ as o,l as i,o as e,c as d,v as t,p as s,x as r,d as m,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"结构化输出的开销","description":"","frontmatter":{"title":"结构化输出的开销","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/structured-output-overhead.md","filePath":"llm/structured-output-overhead.md","lastUpdated":1789023840000}'),c={name:"llm/structured-output-overhead.md"};function u(h,a,E,_,f,A){const l=i("Mermaid");return e(),d("div",null,[a[1]||(a[1]=t('<h1 id="结构化输出的开销" tabindex="-1">结构化输出的开销 <a class="header-anchor" href="#结构化输出的开销" aria-label="Permalink to &quot;结构化输出的开销&quot;">​</a></h1><div class="epigraph"><p>合法集可以预编译成查表，但热路径上仍要取掩码、施加、并与 GPU 前向重叠；结构保证不等于零开销。</p><footer>—— Willard &amp; Louf, Efficient Guided Generation for Large Language Models；CFG 热路径见 Dong et al., XGrammar</footer></div><p><a href="/llm/sampler-kernel">上一课</a>把采样留在设备上，并点出：掩码若在主机生成，内核再快也要等。<a href="/llm/constrained-decoding">约束解码</a>已经说明 FSM / PDA 如何保证 JSON 可解析。本课只补 <em>开销</em>：编译、逐步掩码、与 decode 步的重叠、以及空集回退。产品常把 structured output 当成免费质量；账记在 TTFT 的编译与 TPOT 的掩码上。后课用多样本投票换质量，那是另一张算力账单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无约束采样的逐步额外工作接近一次稀疏 bias。结构化路径每步需要 \\(\\mathcal{M}(s)\\subseteq\\mathcal{V}\\)。Willard 与 Louf 把正则的扫词表挪到编译期，逐步接近查表；XGrammar 用自适应掩码缓存与 GPU 重叠，使 CFG 在服务上可承受。缺口不是再讲自动机，而是：这些「接近常数」在哪些情况下回到线性，以及开销与<a href="/llm/sampling-temperature-topp">核采样</a>谁先谁后。</p><p>三类可见成本：（1）首次见到 schema 的编译（冷启动，打在 TTFT）；（2）逐步取掩码与 D2H/H2D；（3）合法集极小时采样退化，但前向仍付完整 decode。第三项常被忽略：结构不减少权重搬运。</p><p><span class="marginnote">压缩 FSM 在出度为 1 的边上可以不询问模型、直接写确定 token。那一段 <em>跳过了前向</em>，是真的省 decode 步。开销分析必须把「确定边」和「有分支的掩码步」分开，否则会把加速与减速平均成一句「差不多」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把 schema 编译结果按进程缓存：同一 JSON Schema 不应每请求重新建 FSM。热路径：状态 \\(s\\) → 查 \\(\\mathcal{M}(s)\\) → 传到采样核（稀疏下标或 bitmask）→ 与上一拍 GPU 前向重叠下一拍掩码。XGrammar 把与栈无关的 token 类预计算，运行时只处理依赖栈的集合；缓存命中时逐步 CPU 工作可以藏进 GEMM。</p><p>测开销要用两条曲线：相对无约束的 TPOT 比，以及「确定边跳过前向」的步数比。只报前者，会低估键名很多的 schema；只报后者，会低估高度分支的枚举。与连续批混合时，一批里只有部分请求带结构，采样核必须分派，掩码张量不能按最大词表给每条都分配。</p>',10)),(e(),s(p,null,{default:r(()=>[n(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCH%5B%22Schema%22%5D%20--%3E%20COMP%5B%22%E7%BC%96%E8%AF%91%20FSM%2FPDA%22%5D%0A%20%20COMP%20--%3E%20CACHE%5B%22%E8%BF%9B%E7%A8%8B%E7%BA%A7%E7%BC%93%E5%AD%98%22%5D%0A%20%20CACHE%20--%3E%20M%5B%22%E9%80%90%E6%AD%A5%E6%8E%A9%E7%A0%81%20M(s)%22%5D%0A%20%20M%20--%3E%20OV%5B%22%E4%B8%8E%20GPU%20%E5%89%8D%E5%90%91%E9%87%8D%E5%8F%A0%22%5D%0A%20%20M%20--%3E%20SAMP%5B%22%E9%87%87%E6%A0%B7%E5%99%A8%E5%86%85%E6%A0%B8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>掩码是稀疏向量或位图，词表 \\(10^5\\)、batch \\(256\\) 时，稠密 bitmask 已是数 MB 级逐步流量，值得压缩。开销从「CPU 扫词表」变成「PCIe 传掩码」时，重叠才能救；同步点（必须等 CPU 算完 \\(s\\) 才启动核）会把 decode 带宽墙变成 <em>延迟墙</em>。投机时草稿也要走自动机：确定边可以当 \\(\\gamma\\) 很大的免费草稿，分支处接受率受合法集大小限制——合法集越小，草稿越容易猜中，结构化与投机往往 <em>互相帮忙</em>。这与「结构总是变慢」的直觉相反，但只在确定边或小枚举上成立。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要每条消息现场编译巨大 CFG。不要在合法集上再叠很紧的 top-\\(p\\) 而不写回退。不要把结构化准确率写成模型能力：掩码已经禁止了非法 token，解析成功是契约，事实仍可能错。流式 JSON 应对稳定前缀 parse，先修 detokenize。评测延迟必须包含冷编译或明确排除并标注缓存命中。</p><p>出处：Willard &amp; Louf；Dong et al., XGrammar。SGLang 压缩 FSM 是同族工程。不发明 arXiv 号。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>结构化的逐步成本是取掩码与传掩码，不是自动机理论本身。</li><li>编译要缓存；冷启动打在 TTFT。</li><li>确定边可跳过前向，真省步；高度分支则可能同步等待。</li><li>结构不减少权重 IO；合法集小时间谍式加速来自投机接受率。</li><li>与采样核、连续批分派绑定，不能只在 Python 里 <code>if json</code>。</li><li>后课把质量从「一条合法串」换成「多样本再聚合」。</li><li>出处：Willard &amp; Louf；Dong et al., XGrammar。</li></ul>',7))])}const S=o(c,[["render",u]]);export{T as __pageData,S as default};
